// Extract comment/DM data from FB or IG webhook
const body = $input.item.json.body || {};

let plataforma = 'facebook';
let tipo = 'comentario'; // comentario | dm
let mensaje = '';
let comentarioId = '';
let postId = '';
let usuarioId = '';
let usuarioNombre = '';
let mediaId = '';

// Facebook page feed (comments on posts)
if (body.object === 'page') {
  const entry = (body.entry || [])[0] || {};
  const change = (entry.changes || [])[0] || {};
  const val = change.value || {};
  plataforma = 'facebook';

  if (change.field === 'messages') {
    // FB Messenger DM
    tipo = 'dm';
    const msg = (val.messages || [])[0] || {};
    mensaje = msg.text || '';
    usuarioId = val.sender?.id || '';
    comentarioId = msg.mid || '';
  } else {
    // FB comment on post
    tipo = 'comentario';
    mensaje = val.message || '';
    comentarioId = val.comment_id || val.id || '';
    postId = val.post_id || '';
    usuarioId = val.from?.id || '';
    usuarioNombre = val.from?.name || '';
  }
}

// Instagram (comments on media)
if (body.object === 'instagram') {
  const entry = (body.entry || [])[0] || {};
  const change = (entry.changes || [])[0] || {};
  const val = change.value || {};
  plataforma = 'instagram';

  if (change.field === 'messages') {
    tipo = 'dm';
    const msg = (val.messages || [])[0] || {};
    mensaje = msg.text?.body || msg.text || '';
    usuarioId = val.sender?.id || '';
    comentarioId = msg.mid || '';
  } else {
    tipo = 'comentario';
    mensaje = val.text || val.message || '';
    comentarioId = val.id || '';
    mediaId = val.media?.id || '';
    usuarioId = val.from?.id || '';
    usuarioNombre = val.from?.username || '';
  }
}

// Skip if no message or if it's our own reply (avoid loops)
if (!mensaje.trim()) {
  throw new Error('SKIP: empty message');
}

return [{ json: {
  plataforma,
  tipo,
  mensaje,
  comentarioId,
  postId,
  mediaId,
  usuarioId,
  usuarioNombre
}}];

const config = $('⚙️ Config Growth54').item.json;
const evento = $('🔍 Extraer Evento FB/IG').item.json;
const empresaRaw = $('📊 Obtener Perfil Empresa').item.json;
const empresa = empresaRaw.data || empresaRaw || {};
const estRaw = $('🎯 Obtener Estrategia RRSS').item?.json || {};
const estrategia = estRaw.data || estRaw || {};

const nombre_empresa = empresa.name || empresa.nombre || 'Crating Express';
const descripcion = empresa.description || empresa.descripcion || '';
const tono = estrategia.tono || 'profesional, cercano y directo';
const wa_link = config.WA_LINK || 'https://wa.me/17867880417';

// Build system prompt
const promptSistema = `Actúa como un Community Manager experto en conversión, integrando SEO, AEO y GEO.

Empresa: ${nombre_empresa}
Descripción: ${descripcion}
Tono de marca: ${tono}
Link de WhatsApp: ${wa_link}

Tu función es:
- responder con claridad (AEO)
- detectar intención del usuario
- calificar el lead
- guiar la conversación hacia conversión

Debes:
1. Identificar la intención: informacional, comercial o transaccional
2. Responder de forma clara, útil y profesional (máximo 3 oraciones en la respuesta pública)
3. Aportar micro-educación breve si aplica
4. Hacer preguntas inteligentes en secuencia:
   NIVEL 1 (apertura): pregunta abierta universal — NO asumas el producto
   NIVEL 2 (contexto): exportación, transporte dentro de USA o almacenaje
   NIVEL 3 (detalle, opcional): tamaño, peso, condiciones
5. Guiar hacia conversión (WhatsApp, DM)

IMPORTANTE:
- La RESPUESTA debe ser corta y apta para publicar directamente en el comentario/DM
- NO uses markdown, bullets ni emojis excesivos en la respuesta pública
- Sé directo y orientado a conversión
- Evita respuestas genéricas

Entrega EXACTAMENTE en este formato:
INTENCIÓN: [informacional|comercial|transaccional]
RESPUESTA: [texto listo para publicar en redes]
LEAD: [frío|tibio|caliente]
PREGUNTA: [pregunta de calificación para incluir en la respuesta]
SIGUIENTE PASO: [dm|whatsapp|llamada]`;

const mensajeUsuario = `Plataforma: ${evento.plataforma}
Tipo: ${evento.tipo}
Mensaje del usuario: ${evento.mensaje}`;

return [{ json: {
  promptSistema,
  mensajeUsuario,
  evento,
  wa_link,
  empresa_nombre: nombre_empresa
}}];

